const askOccurrenceSummary = `-- name: AskOccurrenceSummary :one

WITH base AS (
    SELECT
        (($1::timestamptz IS NULL AND $2::timestamptz IS NULL)
         OR COALESCE(($1::timestamptz IS NULL OR o.occurred_from >= $1::timestamptz)
             AND ($2::timestamptz IS NULL OR o.occurred_from < $2::timestamptz), FALSE))::bool AS date_ok,
        COALESCE(($3::text IS NULL OR l.uf = $3::text)
            AND ($4::text IS NULL OR l.municipality_code = $4::text)
            AND ($5::text IS NULL OR lower(l.neighbourhood) = lower($5::text))
            AND (cardinality($6::text[]) = 0 OR l.place_type = ANY($6::text[])), FALSE)::bool AS place_ok,
        (o.occurred_from IS NULL)::bool AS undated,
        (o.location_id IS NULL)::bool AS unplaced
    FROM occurrences o
    LEFT JOIN locations l ON l.id = o.location_id
    WHERE (cardinality($7::text[]) = 0 OR EXISTS (
            SELECT 1 FROM occurrence_classifications c WHERE c.occurrence_id = o.id AND c.type_code = ANY($7::text[])))
      AND (cardinality($8::text[]) = 0 OR EXISTS (
            SELECT 1 FROM occurrence_classifications c JOIN occurrence_types t ON t.code = c.type_code
            WHERE c.occurrence_id = o.id AND t.grp = ANY($8::text[])))
      AND (cardinality($9::text[]) = 0 OR o.status = ANY($9::text[]))
      AND ($10::bool IS NULL OR o.attempted = $10::bool)
      AND ($11::text IS NULL OR lower(o.agency) = lower($11::text))
)
SELECT
    COUNT(*) FILTER (WHERE date_ok AND place_ok)::bigint AS matched,
    COUNT(*) FILTER (WHERE undated AND NOT date_ok AND place_ok)::bigint AS undated_excluded,
    COUNT(*) FILTER (WHERE unplaced AND NOT place_ok AND date_ok)::bigint AS unplaced_excluded
FROM base
`

type AskOccurrenceSummaryParams struct {
	OccurredAfter    sql.NullTime   `db:"occurred_after" json:"occurred_after"`
	OccurredBefore   sql.NullTime   `db:"occurred_before" json:"occurred_before"`
	Uf               sql.NullString `db:"uf" json:"uf"`
	MunicipalityCode sql.NullString `db:"municipality_code" json:"municipality_code"`
	Neighbourhood    sql.NullString `db:"neighbourhood" json:"neighbourhood"`
	PlaceTypes       []string       `db:"place_types" json:"place_types"`
	Types            []string       `db:"types" json:"types"`
	Groups           []string       `db:"groups" json:"groups"`
	Statuses         []string       `db:"statuses" json:"statuses"`
	Attempted        sql.NullBool   `db:"attempted" json:"attempted"`
	Agency           sql.NullString `db:"agency" json:"agency"`
}

type AskOccurrenceSummaryRow struct {
	Matched          int64 `db:"matched" json:"matched"`
	UndatedExcluded  int64 `db:"undated_excluded" json:"undated_excluded"`
	UnplacedExcluded int64 `db:"unplaced_excluded" json:"unplaced_excluded"`
}

// The AI mode's read-only queries (ask package, docs/ask-plan.md). The model never writes SQL: it
// chooses a tool, and a tool's filters reach these parameterized queries. An empty array or a NULL
// leaves a filter off. occurred_after is inclusive and occurred_before exclusive; a period counts
// by occurred_from, the start of an occurrence's window.
// How many occurrences match, and how many a period or a place filter left out only because the
// occurrence has no date or no place: an answer has to be able to say so.
func (q *Queries) AskOccurrenceSummary(ctx context.Context, arg AskOccurrenceSummaryParams) (AskOccurrenceSummaryRow, error) {
	row := q.db.QueryRowContext(ctx, askOccurrenceSummary,
		arg.OccurredAfter,
		arg.OccurredBefore,
		arg.Uf,
		arg.MunicipalityCode,
		arg.Neighbourhood,
		pq.Array(arg.PlaceTypes),
		pq.Array(arg.Types),
		pq.Array(arg.Groups),
		pq.Array(arg.Statuses),
		arg.Attempted,
		arg.Agency,
	)
	var i AskOccurrenceSummaryRow
	err := row.Scan(&i.Matched, &i.UndatedExcluded, &i.UnplacedExcluded)
	return i, err
}

