const askPersonsShareParent = `-- name: AskPersonsShareParent :many
SELECT DISTINCT d2.person_id AS person_number
FROM identity_documents d
JOIN identity_registers r ON r.document_id = d.id
JOIN identity_documents d2 ON d2.person_id = ANY($1::bigint[])
JOIN identity_registers r2 ON r2.document_id = d2.id
WHERE d.person_id = $2
  AND (lower(r.parent_1_name) IN (lower(r2.parent_1_name), lower(r2.parent_2_name))
    OR lower(r.parent_2_name) IN (lower(r2.parent_1_name), lower(r2.parent_2_name)))
`

type AskPersonsShareParentParams struct {
	Others       []int64       `db:"others" json:"others"`
	PersonNumber sql.NullInt64 `db:"person_number" json:"person_number"`
}

// Of the given people, those with a parent's name in common with this person, on any register. It
// answers yes or no: the names themselves stay on the person's page.
func (q *Queries) AskPersonsShareParent(ctx context.Context, arg AskPersonsShareParentParams) ([]sql.NullInt64, error) {
	rows, err := q.db.QueryContext(ctx, askPersonsShareParent, pq.Array(arg.Others), arg.PersonNumber)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []sql.NullInt64
	for rows.Next() {
		var person_number sql.NullInt64
		if err := rows.Scan(&person_number); err != nil {
			return nil, err
		}
		items = append(items, person_number)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const askSearchPersons = `-- name: AskSearchPersons :many

SELECT p.id AS person_number, r.name, r.birth_date, r.register_number, d.document_type, d.document_number
FROM identity_registers r
JOIN identity_documents d ON d.id = r.document_id
JOIN persons p ON p.id = d.person_id
WHERE r.name ILIKE '%' || replace(replace(replace($1::text, '\', '\\'), '%', '\%'), '_', '\_') || '%'
ORDER BY r.name, p.id, r.id
LIMIT $2
`

